40	// Recipe key — single source in item-variant.css.ts (SFCC-270 round 2 rework), no longer
41	// redeclared per file.
42	import { ZIMM_CART_ITEM_VARIANT_RECIPE } from './item-variant.css';
43	
44	// See index.tsx's own note on why this is `any` rather than a structural type.
45	type SfccVariant = any;
46	
47	type PricePerItemProps = {
48	  currency: string;
49	  // Deviation from the base file (same labelled-comment convention as
50	  // product-view/index.tsx:659-661/1019-1022): base PropTypes declares this as optional
51	  // (`PropTypes.number`, no `.isRequired`), but both real call sites below it — the only two
52	  // in this file — only ever render <PricePerItem> from behind a `priceData?.pricePerUnit &&`
53	  // guard, so `basePrice` is never actually undefined when this renders. Typed as required to
54	  // satisfy `<FormattedNumber value={basePrice} />`'s `number | bigint` prop under strict null
55	  // checks, without inventing a fallback value the base file never had.
56	  basePrice: number;
57	};
58	
59	const PricePerItem = ({ currency, basePrice }: PricePerItemProps) => {
60	  return (
61	    <Text fontSize={{ base: '12px', lg: '14px' }}>
62	      <FormattedNumber style="currency" currency={currency} value={basePrice} />
63	      <FormattedMessage
64	        defaultMessage="ea"
65	        id="price_per_item.label.each"
66	        description="Abbreviated 'each', follows price per item, like $10/ea"
67	      />
68	    </Text>
69	  );
70	};
71	
72	type ItemPriceProps = {
73	  currency: string;
74	  align?: string;
75	  baseDirection?: string;
76	} & Record<string, any>;
77	
78	/**
79	 * In the context of a cart product item variant, this component renders the item's
80	 * pricing, taking into account applied discounts as well as base item prices.
81	 */
82	const ItemPrice = ({ currency, align = 'right', baseDirection = 'column', ...props }: ItemPriceProps) => {
83	  const variant: SfccVariant = useItemVariant();
84	  const styles = useMultiStyleConfig(ZIMM_CART_ITEM_VARIANT_RECIPE, {});
85	  const { price, priceAfterItemDiscount } = variant;
86	  const isASet = variant?.type?.set;
87	  const isMaster = variant?.type?.master;
88	  let priceData;
89	  // When variant has basket pricing, we should prioritize these prices for displaying
90	  // since they may have take promotion/discount into account
91	  // NOTE: try NOT to re-calculate these values since basket-level discount is complicated
92	  if (variant?.itemId) {
93	    priceData = {
94	      currentPrice: priceAfterItemDiscount,
95	      // we don't want to show strikethrough price for cart since listPrice is not available via basket pricing
96	      listPrice: null,
97	      pricePerUnit: variant?.pricePerUnit,
98	      isASet,
99	      isMaster,
100	      isRange: isASet || isMaster || false,
101	      isOnSale: price > priceAfterItemDiscount,
102	    };
103	  } else {
104	    // for wishlist page we extract price info from variant/product obj
105	    priceData = getPriceData(variant);
106	  }
107	  const isDesktop = useBreakpointValue({ base: false, lg: true });
108	
109	  return (
110	    <Stack
111	      sx={styles.price}
112	      textAlign={align}
113	      direction={baseDirection}
114	      justifyContent={align === 'left' ? 'flex-start' : 'flex-end'}
115	      alignItems="baseline"
116	      spacing={priceData?.isOnSale ? 0 : 1}
117	      wrap="nowrap"
118	      {...props}
119	    >
120	      {!isDesktop && variant?.quantity > 1 && !isASet && priceData?.pricePerUnit && (
121	        <PricePerItem currency={currency} basePrice={priceData.pricePerUnit} />
122	      )}
123	
124	      {variant?.itemId ? (
125	        <DisplayPrice
126	          labelForA11y={variant?.name}
127	          currency={currency}
128	          priceData={priceData}
129	          listPriceProps={{ fontSize: 'sm' }}
130	        />
131	      ) : (
132	        <DisplayPrice
133	          labelForA11y={variant?.name}
134	          currency={currency}
135	          priceData={priceData}
136	          quantity={variant?.quantity}
137	          listPriceProps={{ fontSize: 'sm' }}
138	        />
139	      )}
140	
141	      {isDesktop && variant?.quantity > 1 && !isASet && priceData?.pricePerUnit && (
142	        <PricePerItem currency={currency} basePrice={priceData.pricePerUnit} />
143	      )}
144	    </Stack>
145	  );
